Voici une fonction C++ qui prend une référence à un std::string contenant du texte au format Markdown et renvoie un std::string contenant du texte au format HTML :

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <regex>

std::string convertMarkdownToHtml(const std::string& markdown) {
    std::stringstream ss;
    std::string html;

    // Titres (h1, h2, h3, ...)
    std::regex title_regex("^#{1,6}\\s(.*)$");
    std::smatch title_match;

    if (std::regex_match(markdown, title_match, title_regex)) {
        std::string title = title_match[1].str();
        html += "<h" + std::to_string(title_match.size()) + ">" + title + "</h" + std::to_string(title_match.size()) + ">\n";
    }

    // Texte en gras
    std::regex bold_regex("\\*([^*]+)\\*");
    std::smatch bold_match;

    while (std::regex_search(markdown, bold_match, bold_regex)) {
        std::string text = bold_match[1].str();
        html += "<strong>" + text + "</strong>\n";
        markdown = bold_match.suffix().str();
    }

    // Texte en italique
    std::regex italic_regex("_(.+?)_");
    std::smatch italic_match;

    while (std::regex_search(markdown, italic_match, italic_regex)) {
        std::string text = italic_match[1].str();
        html += "<em>" + text + "</em>\n";
        markdown = italic_match.suffix().str();
    }

    // Lien
    std::regex link_regex("\\[([^\\]]+)]\\(([^\\)]+)\\)");
    std::smatch link_match;

    while (std::regex_search(markdown, link_match, link_regex)) {
        std::string text = link_match[1].str();
        std::string href = link_match[2].str();
        html += "<a href='" + href + "'>" + text + "</a>\n";
        markdown = link_match.suffix().str();
    }

    // Liste
    std::regex list_regex("^\\s*([-+*]\\s.+)\\n\\s*(?=\\1(?!\\s*$))");
    std::smatch list_match;

    while (std::regex_search(markdown, list_match, list_regex)) {
        std::string list_item = list_match[1].str();
        html += "<ul>\n";
        std::string list_item_markdown = list_item.substr(2);
        std::string list_item_html;

        // Sous-liste
        std::regex nested_list_regex("^\\s*([-+*]\\s.+)\\n\\s*(?=\\1(?!\\s*$))");
        std::smatch nested_list_match;

        while (std::regex_search(list_item_markdown, nested_list_match, nested_list_regex)) {
            std::string nested_list_item = nested_list_match[1].str();
            list_item_html += "<li>" + convertMarkdownToHtml(nested_list_item) + "</li>\n";
            list_item_markdown = nested_list_match.suffix().str();
        }

        list_item_html += "</ul>\n";
        html += list_item_html;
        markdown = list_match.suffix().str();
    }

    // Paragraphe
    std::regex paragraph_regex("(?:(?!\\n\\s*\\-{3,}|\\n\\s*\\#{1,6}\\s).)*");
    std::smatch paragraph_match;

    while (std::regex_search(markdown, paragraph_match, paragraph_regex)) {
        std::string paragraph = paragraph_match[0].str();
        html += "<p>" + paragraph + "</p>\n";
        markdown = paragraph_match.suffix().str();
    }

    ss << html;
    return ss.str();
}

int main() {
    std::string markdown = "H1: # Titre\n"
                            "Texte en gras: *Texte en gras*\n"
                            "Texte en italique: _Texte en italique_\n"
                            "[Lien](https://example.com)\n"
                            "- Item 1\n"
                            "  - Sous-item 1\n"
                            "  - Sous-item 2\n"
                            "- Item 2\n"
                            "Paragraphe: Une ligne de texte.\n"
                            "Une deuxième ligne.";

    std::string html = convertMarkdownToHtml(markdown);
    std::cout << html << std::endl;

    return 0;
}
```

Cette fonction utilise des expressions régulières pour détecter les différents éléments de Markdown, puis les convertit en HTML correspondant. Elle peut également gérer les listes imbriquées (sous-listes) en utilisant une expression régulière supplémentaire. Notez que cette fonction ne traite pas tous les éléments de Markdown, mais seulement ceux que l'on rencontre habituellement dans les documents Markdown.

